def validate_username(username):
  valid = True
  # length check
  if len(username) < 8:
    valid = False
  elif (not username[0].isupper()):
    valid = False
  elif (not username[-2].islower()):
    valid = False
  elif (not username[-1].isdigit()):
    valid = False
  return valid
